using System.Text.Json;
using VelaRay.Core.Platform;
using VelaRay.Maui.Localization;

namespace VelaRay.Maui;

/// <summary>Read-only display of the exact config passed to V2Fly or newly generated by the UI.</summary>
public partial class ConfigViewerPage : ContentPage
{
    private readonly string _originalJson;
    private readonly string _path;
    private readonly IFileLocationService _fileLocations;

    public ConfigViewerPage(string path, string json, bool isRunning, IFileLocationService fileLocations, string format = "V5")
    {
        InitializeComponent();
        _path = Path.GetFullPath(path);
        _originalJson = json;
        _fileLocations = fileLocations;
        CaptionLabel.Text = (isRunning ? UiStrings.Instance.Translate("当前运行配置") : UiStrings.Instance.Translate("最终生成配置")) + $" · JSON {format}";
        DescriptionLabel.Text = UiStrings.Instance.Translate(isRunning
            ? "这是启动 v2ray-core 时使用的配置快照。编辑表单不会改变当前连接，重新连接后才生效。"
            : "这是根据当前界面设置生成的完整配置（或选定的外部 JSON 文件）；需要连接/重新连接才会生效。");
        ConfigPathLabel.Text = _path;
        RefreshText();
    }

    private void RefreshText()
    {
        if (!FormatSwitch.IsToggled)
        {
            ConfigTextLabel.Text = _originalJson;
            return;
        }
        try
        {
            using var document = JsonDocument.Parse(_originalJson);
            ConfigTextLabel.Text = JsonSerializer.Serialize(document.RootElement, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (JsonException)
        {
            // Validation will report malformed JSON; still show exact source for diagnosis.
            ConfigTextLabel.Text = _originalJson;
        }
    }

    private void FormatChanged(object sender, ToggledEventArgs e)
    {
        // MAUI can trigger Toggled during XAML initialization, before fields are assigned.
        if (_originalJson is not null) RefreshText();
    }

    private async void CopyClicked(object sender, EventArgs e)
    {
        await Clipboard.Default.SetTextAsync(_originalJson);
        await DisplayAlert(UiStrings.Instance.Translate("已复制"), UiStrings.Instance.Translate("已复制原始 JSON（包含配置中的凭据）。"), "OK");
    }

    private async void RevealClicked(object sender, EventArgs e)
    {
        try { _fileLocations.RevealFile(_path); }
        catch (Exception ex) { await DisplayAlert(UiStrings.Instance.Translate("无法定位配置文件"), ex.Message, "OK"); }
    }

    private async void CloseClicked(object sender, EventArgs e) => await Navigation.PopModalAsync();
}
